/*******************************************************************************
 * Function:  Packet-->Memory Mapped Transaction Converter
 * Author:    Andreas Olofsson
 * License:   MIT (see LICENSE file in OH! repository)
 *
 * Documentation:
 *
 * see ./emesh_pack.v for packet formatting
 *
 ******************************************************************************/
module emesh_unpack
  #(parameter AW = 32,   // address width
    parameter PW = 104)  // packet width
   (
    //Input packet
    input [PW-1:0]    packet_in,
    //Write
    output 	      cmd_write,//start write
    output 	      cmd_write_stop,//stop burst
    //Read
    output 	      cmd_read,
    //Atomic read/write
    output 	      cmd_atomic_add,
    output 	      cmd_atomic_and,
    output 	      cmd_atomic_or,
    output 	      cmd_atomic_xor,
    output 	      cmd_cas,
    //Command Fields
    output [3:0]      cmd_opcode,//raw opcode
    output [3:0]      cmd_length,//bust length(up to 16)
    output [2:0]      cmd_size,//size of each transfer
    output [7:0]      cmd_user, //user field
    //Address/Data
    output [AW-1:0]   dstaddr, // read/write target address
    output [AW-1:0]   srcaddr, // read return address
    output [2*AW-1:0] data     // write data
    );

   wire [15:0] cmd;

   //############################################
   // Command Decode
   //############################################

   emesh_decode emesh_decode (//Input
			      .cmd_in		(cmd[15:0]),
			      // Outputs
			      .cmd_write	(cmd_write),
			      .cmd_write_stop	(cmd_write_stop),
			      .cmd_read		(cmd_read),
			      .cmd_cas		(cmd_cas),
			      .cmd_atomic_add	(cmd_atomic_add),
			      .cmd_atomic_and	(cmd_atomic_and),
			      .cmd_atomic_or	(cmd_atomic_or),
			      .cmd_atomic_xor	(cmd_atomic_xor),
			      .cmd_opcode	(cmd_opcode[3:0]),
			      .cmd_user		(cmd_user[7:0]),
			      .cmd_length	(cmd_length[3:0]),
			      .cmd_size		(cmd_size[2:0]));
   generate
      //######################
      // 16-Bit ("lite/apb like")
      //######################
      if(AW==16) begin : aw16
	 if(PW==40) begin : p40
	    assign cmd[7:0]      = packet_in[7:0];
	    assign cmd[15:8]     = 8'b0;
	    assign dstaddr[15:0] = packet_in[23:8];
	    assign srcaddr[15:0] = packet_in[39:24];
	    assign data[31:0]    = {16'b0,packet_in[39:24]};
	 end
	 else begin: perror
	    initial
	      $display ("Combo not supported (PW=%ds AW==%ds)", PW,AW);
	 end
      end // block: aw16
      //######################
      // 32-Bit
      //######################
      if(AW==32) begin : aw32
	if(PW==80) begin: p80
	   assign cmd[15:0]     = packet_in[15:0];
	   assign dstaddr[31:0] = packet_in[47:16];
	   assign srcaddr[31:0] = packet_in[79:48];
	   assign data[31:0]    = packet_in[79:48];
	   assign data[63:32]   = 32'b0;
	end
	else if(PW==112) begin: p112
	   assign cmd[15:0]     = packet_in[15:0];
	   assign dstaddr[31:0] = packet_in[47:16];
	   assign srcaddr[31:0] = packet_in[79:48];
	   assign data[63:0]    = packet_in[111:48];
	end
	else begin: perror
	   initial
	     $display ("Combo not supported (PW=%ds AW==%ds)", PW,AW);
	end
      end // block: aw32
      //######################
      // 64-Bit
      //######################
      if(AW==64) begin : aw64
	 if(PW==144) begin: p144
	    assign cmd[15:0]      = packet_in[15:0];
	    assign dstaddr[31:0]  = packet_in[47:16];
	    assign srcaddr[63:0]  = packet_in[111:48];
	    assign data[127:0]    = packet_in[111:48];
	    assign dstaddr[63:32] = packet_in[143:112];
	    assign data[127:64]   = 64'b0;
	 end
	 else if(PW==208) begin: p208
	    assign cmd[15:0]      = packet_in[15:0];
	    assign dstaddr[31:0]  = packet_in[47:16];
	    assign srcaddr[63:0]  = packet_in[111:48];
	    assign data[63:0]     = packet_in[111:48];
	    assign dstaddr[63:32] = packet_in[143:112];
	    assign data[127:64]   = packet_in[207:144];
	 end
	 else begin: perror
	    initial
	      $display ("Combo not supported (PW=%ds AW==%ds)", PW,AW);
	 end
      end // block: aw64
      //######################
      // 128-Bit
      //######################
      if(AW==128) begin : aw128
	if(PW==272) begin: p272
	   assign cmd[15:0]       = packet_in[15:0];
	   assign dstaddr[31:0]   = packet_in[47:16];
	   assign srcaddr[63:0]   = packet_in[111:48];
	   assign data[63:0]      = packet_in[111:48];
	   assign dstaddr[63:32]  = packet_in[143:112];
	   assign data[127:64]    = packet_in[207:144];
	   assign srcaddr[127:64] = packet_in[207:144];
	   assign dstaddr[127:64] = packet_in[271:208];
	   assign data[255:128]   = 128'b0;
	 end
	else if(PW==400) begin: p400
	   assign cmd[15:0]       = packet_in[15:0];
	   assign dstaddr[31:0]   = packet_in[47:16];
	   assign srcaddr[63:0]   = packet_in[111:48];
	   assign data[63:0]      = packet_in[111:48];
	   assign dstaddr[63:32]  = packet_in[143:112];
	   assign data[127:64]    = packet_in[207:144];
	   assign srcaddr[127:64] = packet_in[207:144];
	   assign dstaddr[127:64] = packet_in[271:208];
	   assign data[255:128]   = packet_in[399:272];
	end
	else begin: perror
	   initial
	     $display ("Combo not supported (PW=%ds AW==%ds)", PW,AW);
	end
      end // block: aw128
   endgenerate

endmodule // enoc_unpack

/* Aligns data before writing.
 * Incoming data is aligned to lsb's
 */ 
module emesh_wralign (/*AUTOARG*/
   // Outputs
   data_out,
   // Inputs
   datamode, data_in
   );

   input  [1:0]    datamode;
   input  [63:0]   data_in;
   output [63:0]   data_out;

   wire [3:0] data_size;

   assign data_size[0]= (datamode[1:0]==2'b00);//byte
   assign data_size[1]= (datamode[1:0]==2'b01);//short
   assign data_size[2]= (datamode[1:0]==2'b10);//word
   assign data_size[3]= (datamode[1:0]==2'b11);//double

   //B0(0)
   assign data_out[7:0]   = data_in[7:0];

   //B1(16 NAND2S,8 NOR2S)
   assign data_out[15:8]  = {(8){data_size[0]}}      & data_in[7:0]   |
                            {(8){(|data_size[3:1])}} & data_in[15:8] ;

   //B2(16 NAND2S,8 NOR2S)
   assign data_out[23:16] = {(8){(|data_size[1:0])}} & data_in[7:0]   |
                            {(8){(|data_size[3:2])}} & data_in[23:16] ; 

   //B3(24 NAND2S,8 NOR3S)
   assign data_out[31:24] = {(8){data_size[0]}}      & data_in[7:0]   |
                            {(8){data_size[1]}}      & data_in[15:8]  |
                            {(8){(|data_size[3:2])}} & data_in[31:24] ; 

   //B4(24 NAND2S,8 NOR3S)
   assign data_out[39:32] = {(8){(|data_size[2:0])}} & data_in[7:0]   |
                            {(8){data_size[3]}}      & data_in[39:32] ;

   //B5(24 NAND2S,8 NOR3S)
   assign data_out[47:40] = {(8){data_size[0]}}      & data_in[7:0]   |
                            {(8){(|data_size[2:1])}} & data_in[15:8]  |
                            {(8){data_size[3]}}      & data_in[47:40] ;

   //B6(24 NAND2S,8 NOR3S)
   assign data_out[55:48] = {(8){(|data_size[1:0])}} & data_in[7:0]   |
                            {(8){data_size[2]}}      & data_in[23:16] |
                            {(8){data_size[3]}}      & data_in[55:48] ;

   //B7(32 NAND2S,16 NOR2S)
   assign data_out[63:56] = {(8){data_size[0]}}      & data_in[7:0]   |
                            {(8){data_size[1]}}      & data_in[15:8]  |
                            {(8){data_size[2]}}      & data_in[31:24] |
                            {(8){data_size[3]}}      & data_in[63:56] ;

endmodule // memory_wralign

   //Byte Mode:
   //ADDR[2:0]   B7 B6 B5 B4  B3 B2 B1 B0
   //x00         0  0  0  MB0 0  0  0  MB0
   //x01         0  0  0  MB1 0  0  0  MB1
   //x10         0  0  0  MB2 0  0  0  MB2
   //x11         0  0  0  MB3 0  0  0  MB3

   //Short Mode:
   //ADDR[2:0]   B7 B6 B5  B4  B3 B2 B1  B0
   //x00         0  0  MB1 MB0 0  0  MB1 MB0
   //x10         0  0  MB3 MB2 0  0  MB3 MB2

   //Word Mode:
   //ADDR[2:0]   B7  B6  B5  B4  B3  B2  B1  B0
   //x00         MB3 MB2 MB1 MB0 MB3 MB2 MB1 MB0

   //Double Mode:
   //ADDR[2:0]   B7  B6  B5  B4  B3  B2  B1  B0
   //000         MB7 MB6 MB5 MB4 MB3 MB2 MB1 MB0


   //so..
   //B0=MB0|MB1|MB2|MB3
   //B1=MB1|MB3|0
   //B2=MB2|0
   //B3=MB3|0

/*Aligns word on read
 */

module emesh_rdalign (/*AUTOARG*/
   // Outputs
   data_out,
   // Inputs
   addr, datamode, data_in
   );

   //Inputs
   input [2:0] 	   addr;
   input [1:0] 	   datamode; 	   
   input [63:0]    data_in;

   //Outputs
   output [63:0]   data_out;

   //wires
   wire [3:0]      byte0_sel;
   wire [31:0]     data_mux;
   wire [31:0]     data_aligned;
   wire 	   byte1_sel1;
   wire 	   byte1_sel0;
   wire 	   byte2_en;
   wire 	   byte3_en;

   //Shift down high word
   assign data_mux[31:0] = addr[2] ? data_in[63:32] : 
			             data_in[31:0];

   //Byte0
   assign    byte0_sel[3] = addr[1:0]==2'b11;
   assign    byte0_sel[2] = addr[1:0]==2'b10;   
   assign    byte0_sel[1] = addr[1:0]==2'b01;
   assign    byte0_sel[0] = addr[1:0]==2'b00;

   //Byte1  
   assign    byte1_sel1 = datamode[1:0]==2'b01 & addr[1:0]==2'b10;

   assign    byte1_sel0 = (datamode[1:0]==2'b01 & addr[1:0]==2'b00) |
	                  datamode[1:0]==2'b10                      | 
			  datamode[1:0]==2'b11;
   //Byte2
   assign    byte2_en = datamode[1:0]==2'b10 | 
		        datamode[1:0]==2'b11;
   //Byte3
   assign    byte3_en = datamode[1:0]==2'b10 | 
		        datamode[1:0]==2'b11;

   //B0: 32 NANDs,8 NORS
   assign data_aligned[7:0]   = {(8){byte0_sel[3]}} & data_mux[31:24] |
	                        {(8){byte0_sel[2]}} & data_mux[23:16] |
	                        {(8){byte0_sel[1]}} & data_mux[15:8]  |
	                        {(8){byte0_sel[0]}} & data_mux[7:0];
   //B1:
   assign data_aligned[15:8]  = {(8){byte1_sel1}} & data_mux[31:24] |
	                        {(8){byte1_sel0}} & data_mux[15:8];

   //B2: 8 NANDS
   assign data_aligned[23:16] = {(8){byte2_en}} & data_mux[23:16];

   //B3: 
   assign data_aligned[31:24] = {(8){byte3_en}} & data_mux[31:24];

   //lower 32 bits
   assign data_out[31:0]      = data_aligned[31:0];

   //Upper 32 bits are pass through
   assign data_out[63:32]     = data_in[63:32];

endmodule // memory_rdalign

module emesh_readback (/*AUTOARG*/
   // Outputs
   ready_out, access_out, packet_out,
   // Inputs
   nreset, clk, access_in, packet_in, read_data, ready_in
   );
   parameter  AW  = 32;    // address width
   parameter  PW  = 104;   // packet width   

   //clk, reset
   input           nreset;      // asynchronous active low reset
   input 	   clk;         // clock

   // input transaction
   input 	   access_in;   // register access
   input [PW-1:0]  packet_in;   // data/address
   output 	   ready_out;    // pushback from mesh

   // register/memory data (already pipelined)
   input [63:0]    read_data;   // data from register/memorye

   // output transaction
   output 	   access_out;  // register access
   output [PW-1:0] packet_out;  // data/address
   input 	   ready_in;     // pushback from mesh

   /*AUTOWIRE*/
   // Beginning of automatic wires (for undeclared instantiated-module outputs)
   wire [12:0]		ctrlmode_in;		// From p2e of packet2emesh.v
   wire [AW-1:0]	data_in;		// From p2e of packet2emesh.v
   wire [1:0]		datamode_in;		// From p2e of packet2emesh.v
   wire [AW-1:0]	dstaddr_in;		// From p2e of packet2emesh.v
   wire [AW-1:0]	srcaddr_in;		// From p2e of packet2emesh.v
   wire			write_in;		// From p2e of packet2emesh.v
   // End of automatics

   reg [1:0] 		datamode_out;
   reg [4:0] 		ctrlmode_out;
   reg [AW-1:0] 	dstaddr_out; 	
   wire [AW-1:0] 	data_out;
   wire [AW-1:0] 	srcaddr_out;
   reg 			access_out;

   //########################################
   //# Parse packet
   //#######################################  

   enoc_unpack #(.AW(AW),
		 .PW(PW))
   p2e (/*AUTOINST*/
	// Outputs
	.write_in			(write_in),
	.datamode_in			(datamode_in[1:0]),
	.ctrlmode_in			(ctrlmode_in[12:0]),
	.dstaddr_in			(dstaddr_in[AW-1:0]),
	.srcaddr_in			(srcaddr_in[AW-1:0]),
	.data_in			(data_in[AW-1:0]),
	// Inputs
	.packet_in			(packet_in[PW-1:0]));

   //########################################
   //# Pipeline
   //#######################################   

   //access
   always @ (posedge clk or negedge nreset)
     if(!nreset)
       access_out <= 1'b0;
     else if(ready_in)
       access_out <= access_in & ~write_in;

   //packet
   always @ (posedge clk)
     if(ready_in & access_in & ~write_in)
       begin	  
	  datamode_out[1:0]   <= datamode_in[1:0];
	  ctrlmode_out[4:0]   <= ctrlmode_in[4:0];
	  dstaddr_out[AW-1:0] <= srcaddr_in[AW-1:0]; 
       end

   assign data_out[AW-1:0]    = read_data[31:0];
   assign srcaddr_out[AW-1:0] = read_data[63:32];

   //ready signal
   assign ready_out = ready_in;

   //########################################
   //# Convert to Packet
   //#######################################  

   enoc_pack #(.AW(AW),
	       .PW(PW))
   e2p (.write_out   (1'b1),
	/*AUTOINST*/
	// Outputs
	.packet_out			(packet_out[PW-1:0]),
	// Inputs
	.datamode_out			(datamode_out[1:0]),
	.ctrlmode_out			(ctrlmode_out[12:0]),
	.dstaddr_out			(dstaddr_out[AW-1:0]),
	.data_out			(data_out[AW-1:0]),
	.srcaddr_out			(srcaddr_out[AW-1:0]));


endmodule // emesh_readback

